using System.Security.Claims; using Marina.Application.Abstractions; using Marina.Domain.Commerce; using Marina.Persistence.Data; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace Marina.Api.Controllers;
[ApiController,Route("api/v1/payments")]
public sealed class PaymentsController(MarinaDbContext db,IEnumerable<IPaymentProvider>providers):ControllerBase{public sealed record StartPaymentRequest(string Provider,string IdempotencyKey);
 [Authorize,HttpGet("{id:guid}")]public async Task<ActionResult>Status(Guid id,CancellationToken ct){var payment=await db.Payments.AsNoTracking().Where(x=>x.Id==id&&db.Orders.Any(o=>o.Id==x.OrderId&&o.UserId==UserId())).Select(x=>new{x.Id,x.OrderId,x.Provider,x.Status,x.Amount,x.Currency,x.CreatedUtc}).SingleOrDefaultAsync(ct);return payment is null?NotFound():Ok(payment);}
 [Authorize,HttpPost("orders/{orderId:guid}")]public async Task<ActionResult>Start(Guid orderId,StartPaymentRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.IdempotencyKey)||r.IdempotencyKey.Length>100||string.IsNullOrWhiteSpace(r.Provider))return BadRequest();var userId=UserId();var order=await db.Orders.SingleOrDefaultAsync(x=>x.Id==orderId&&x.UserId==userId,ct)??throw new KeyNotFoundException("Order not found.");if(order.Status is OrderStatus.Cancelled or OrderStatus.Refunded)return Conflict(new{message="Order is not payable."});var providerName=r.Provider.Trim();var existing=await db.Payments.SingleOrDefaultAsync(x=>x.OrderId==order.Id&&x.Provider==providerName&&x.IdempotencyKey==r.IdempotencyKey,ct);if(existing is not null)return Ok(new{existing.Id,existing.Status,existing.Provider});if(providerName.Equals("CashOnDelivery",StringComparison.OrdinalIgnoreCase)){var existingCod=await db.Payments.SingleOrDefaultAsync(x=>x.OrderId==order.Id&&x.Provider=="CashOnDelivery",ct);if(existingCod is not null)return Ok(new{existingCod.Id,existingCod.Status,existingCod.Provider});var cod=new Payment{OrderId=order.Id,Provider="CashOnDelivery",Status=PaymentStatus.Pending,Amount=order.Total,Currency="SAR",IdempotencyKey=r.IdempotencyKey};cod.Transactions.Add(new PaymentTransaction{ProviderReference=order.PublicNumber,EventType="CashOnDeliverySelected",PayloadHash=$"cod-selected:{order.Id:N}"});db.Payments.Add(cod);try{await db.SaveChangesAsync(ct);}catch(DbUpdateException){var replay=await db.Payments.AsNoTracking().SingleOrDefaultAsync(x=>x.OrderId==order.Id&&x.Provider=="CashOnDelivery",ct);if(replay is not null)return Ok(new{replay.Id,replay.Status,replay.Provider});throw;}return Ok(new{cod.Id,cod.Status,cod.Provider});}var provider=providers.SingleOrDefault(x=>x.Name.Equals(providerName,StringComparison.OrdinalIgnoreCase));if(provider is null)return StatusCode(503,new ProblemDetails{Status=503,Title="The selected payment provider is not configured."});var payment=new Payment{OrderId=order.Id,Provider=provider.Name,Status=PaymentStatus.Pending,Amount=order.Total,Currency="SAR",IdempotencyKey=r.IdempotencyKey};db.Payments.Add(payment);try{await db.SaveChangesAsync(ct);}catch(DbUpdateException){var replay=await db.Payments.AsNoTracking().SingleOrDefaultAsync(x=>x.OrderId==order.Id&&x.Provider==provider.Name&&x.IdempotencyKey==r.IdempotencyKey,ct);if(replay is not null)return Ok(new{replay.Id,replay.Status,replay.Provider});throw;}var reference=await provider.CreatePaymentAsync(order.Id,order.Total,"SAR",r.IdempotencyKey,ct);payment.Transactions.Add(new PaymentTransaction{ProviderReference=reference,EventType="PaymentCreated",PayloadHash=$"server-created:{payment.Id:N}"});await db.SaveChangesAsync(ct);return Ok(new{payment.Id,payment.Status,payment.Provider,providerReference=reference});}
 [AllowAnonymous,HttpPost("webhooks/{providerName}")]public async Task<IActionResult>Webhook(string providerName,CancellationToken ct){var provider=providers.SingleOrDefault(x=>x.Name.Equals(providerName,StringComparison.OrdinalIgnoreCase));if(provider is null)return NotFound();Request.EnableBuffering();await using var memory=new MemoryStream();await Request.Body.CopyToAsync(memory,ct);if(memory.Length>1024*1024)return BadRequest();var payload=memory.ToArray();var signature=Request.Headers["X-Webhook-Signature"].ToString();if(string.IsNullOrWhiteSpace(signature)||!provider.ValidateWebhook(payload,signature))return Unauthorized();var payloadHash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(payload));if(await db.PaymentTransactions.AnyAsync(x=>x.PayloadHash==payloadHash,ct))return Ok();var parsed=await provider.ParseWebhookAsync(payload,ct);var payment=await db.Payments.SingleOrDefaultAsync(x=>x.Id==parsed.PaymentId&&x.Provider==provider.Name,ct)??throw new KeyNotFoundException("Payment not found.");payment.Status=parsed.Status;payment.Transactions.Add(new PaymentTransaction{ProviderReference=parsed.ProviderReference,EventType=parsed.EventType,PayloadHash=payloadHash});if(parsed.Status==PaymentStatus.Refunded){var request=await db.ReturnRequests.Include(x=>x.StatusHistory).Include(x=>x.Order).ThenInclude(x=>x.StatusHistory).Where(x=>x.OrderId==payment.OrderId&&x.Status==ReturnStatus.RefundPending).OrderByDescending(x=>x.CreatedUtc).FirstOrDefaultAsync(ct);if(request is not null){request.Status=ReturnStatus.Refunded;request.ResolvedUtc=DateTime.UtcNow;request.StatusHistory.Add(new ReturnStatusHistory{Status=ReturnStatus.Refunded,Note="Refund confirmed by payment provider"});request.Order.Status=OrderStatus.Refunded;request.Order.StatusHistory.Add(new OrderStatusHistory{Status=OrderStatus.Refunded,Reason=$"Refund confirmed for {request.PublicNumber}"});}}await db.SaveChangesAsync(ct);return Accepted();}
 private Guid UserId()=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);}
